"""Money helpers: integer cents, decimal rounding, data table."""
import os
from decimal import Decimal
import tomllib

_MODES = {
    "ROUND_UP", "ROUND_DOWN", "ROUND_CEILING", "ROUND_FLOOR",
    "ROUND_HALF_UP", "ROUND_HALF_DOWN", "ROUND_HALF_EVEN", "ROUND_05UP",
}

DEFAULT_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data.toml")


def load_config(path=None):
    with open(path or DEFAULT_PATH, "rb") as f:
        return tomllib.load(f)


def valid_mode(mode):
    return mode in _MODES


def round_cents(value, mode):
    """Round a Decimal amount of cents to an int using a decimal rounding constant."""
    return int(Decimal(value).quantize(Decimal(1), rounding=mode))


def list_price(unit_cost, markup, mode):
    return round_cents(Decimal(unit_cost) * (1 + Decimal(str(markup))), mode)


def sale_revenue(price, qty, threshold, discount_pct, mode):
    gross = Decimal(price) * qty
    if qty >= threshold:
        gross = gross * (100 - Decimal(str(discount_pct))) / 100
    return round_cents(gross, mode)


def late_payment(cost, penalty_pct, mode):
    return round_cents(Decimal(cost) * (100 - Decimal(str(penalty_pct))) / 100, mode)
