"""Supplier reliability rules."""

START = 3
MIN, MAX = 0, 5
REINSTATED = 2


def is_suspended(reliability):
    return reliability <= 1


def after_delivery(reliability, late):
    r = reliability + (-1 if late else 1)
    return max(MIN, min(MAX, r))
