"""Seeded demand simulation."""
import random

from money import load_config


def simulate(days, seed, data_path=None):
    demand = load_config(data_path)["demand"]
    rng = random.Random(seed)
    out = []
    for _ in range(days):
        day = []
        for sku in sorted(demand):
            d = demand[sku]
            q = rng.randint(d["min"], d["max"])
            if q > 0:
                day.append((sku, q))
        out.append(day)
    return out
