"""Depot: multi-warehouse inventory with a cash ledger."""
import copy
import json

import events
import money
import suppliers


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _posint(q):
    if not isinstance(q, int) or isinstance(q, bool) or q <= 0:
        raise DepotError("BAD_QTY")


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, *,
                 late_penalty_pct=None, restock_returned_perishables=None,
                 data_path=None):
        if not money.valid_mode(rounding_mode):
            raise DepotError("BAD_ROUNDING")
        self._cfg = money.load_config(data_path)
        self._mode = rounding_mode
        self._late_pct = late_penalty_pct
        self._restock = restock_returned_perishables
        self._wh = list(warehouses)
        self._cap = {w: capacities[w] for w in self._wh}
        self._s = {
            "warehouses": list(self._wh),
            "items": {}, "lots": {}, "below": {},
            "cash": opening_cash, "day": 0, "notes": [],
            "rel": {}, "orders": {}, "next_order": 1,
            "shipped": {}, "returned": {}, "ship_log": [], "hist": {},
            "overdrawn": False,
        }
        self._undo = None
        self._blocked = False

    # ---- plumbing
    def _op(self, fn, *a, blocks=False):
        snap = copy.deepcopy(self._s)
        try:
            r = fn(*a)
        except BaseException:
            self._s = snap
            raise
        self._undo = None if blocks else snap
        self._blocked = blocks
        return r

    def _sku(self, sku):
        if sku not in self._s["items"]:
            raise DepotError("UNKNOWN_SKU")

    def _w(self, wh):
        if wh not in self._wh:
            raise DepotError("UNKNOWN_WAREHOUSE")

    def _set_cash(self, v):
        self._s["cash"] = v
        if v >= 0:
            self._s["overdrawn"] = False

    def _units(self, wh):
        return sum(q for sku in self._s["lots"] for _, q in self._s["lots"][sku][wh])

    def _held(self):
        return sum(self._units(w) for w in self._wh)

    def _stock(self, sku, wh):
        return sum(q for _, q in self._s["lots"][sku][wh])

    def _add_lot(self, sku, wh, day, qty):
        lots = self._s["lots"][sku][wh]
        for lot in lots:
            if lot[0] == day:
                lot[1] += qty
                break
        else:
            lots.append([day, qty])
            lots.sort(key=lambda l: l[0])
        self._rearm(sku, wh)

    def _rearm(self, sku, wh):
        if self._stock(sku, wh) > self._s["items"][sku]["reorder_level"]:
            self._s["below"][sku][wh] = False

    def _take(self, sku, wh, qty):
        lots = self._s["lots"][sku][wh]
        taken, need = [], qty
        while need > 0:
            lot = lots[0]
            n = min(need, lot[1])
            taken.append([lot[0], n])
            lot[1] -= n
            need -= n
            if lot[1] == 0:
                lots.pop(0)
        return taken

    def _check_cap(self, wh, qty):
        if self._units(wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")

    # ---- items
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        return self._op(self._add_item, sku, unit_cost, reorder_level, shelf_life_days)

    def _add_item(self, sku, unit_cost, reorder_level, shelf):
        if sku in self._s["items"]:
            raise DepotError("DUPLICATE_SKU")
        if not isinstance(unit_cost, int) or unit_cost <= 0:
            raise DepotError("BAD_COST")
        if not isinstance(reorder_level, int) or reorder_level < 0:
            raise DepotError("BAD_LEVEL")
        if shelf is not None and (not isinstance(shelf, int) or shelf < 1):
            raise DepotError("BAD_SHELF_LIFE")
        self._s["items"][sku] = {"unit_cost": unit_cost,
                                 "reorder_level": reorder_level,
                                 "shelf_life_days": shelf}
        self._s["lots"][sku] = {w: [] for w in self._wh}
        self._s["below"][sku] = {w: False for w in self._wh}
        self._s["shipped"][sku] = 0
        self._s["returned"][sku] = 0

    # ---- receive
    def receive(self, sku, qty, wh):
        return self._op(self._receive, sku, qty, wh)

    def _receive(self, sku, qty, wh):
        self._sku(sku)
        self._w(wh)
        _posint(qty)
        if self._s["cash"] < 0:
            raise DepotError("OVERDRAWN")
        self._check_cap(wh, qty)
        cost = self._s["items"][sku]["unit_cost"] * qty
        if self._s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._set_cash(self._s["cash"] - cost)
        self._add_lot(sku, wh, self._s["day"], qty)

    def receive_bulk(self, receipts):
        return self._op(self._bulk, list(receipts))

    def _bulk(self, receipts):
        for sku, qty, wh in receipts:
            self._receive(sku, qty, wh)

    # ---- ship / return
    def list_price(self, sku):
        self._sku(sku)
        return money.list_price(self._s["items"][sku]["unit_cost"],
                                self._cfg["markup"], self._mode)

    def ship(self, sku, qty, wh, price):
        return self._op(self._ship, sku, qty, wh, price)

    def _ship(self, sku, qty, wh, price):
        self._sku(sku)
        self._w(wh)
        _posint(qty)
        if self._stock(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        self._take(sku, wh, qty)
        rev = money.sale_revenue(price, qty, self._cfg["bulk_threshold"],
                                 self._cfg["bulk_discount_pct"], self._mode)
        self._set_cash(self._s["cash"] + rev)
        self._s["shipped"][sku] += qty
        self._s["ship_log"].append([self._s["day"], qty])
        level = self._s["items"][sku]["reorder_level"]
        if self._stock(sku, wh) <= level and not self._s["below"][sku][wh]:
            self._s["below"][sku][wh] = True
            events.emit(self._s, "REORDER", sku, wh)

    def return_goods(self, sku, qty, wh, price):
        return self._op(self._return, sku, qty, wh, price)

    def _return(self, sku, qty, wh, price):
        self._sku(sku)
        self._w(wh)
        _posint(qty)
        if qty > self._s["shipped"][sku] - self._s["returned"][sku]:
            raise DepotError("RETURN_EXCEEDS")
        perishable = self._s["items"][sku]["shelf_life_days"] is not None
        restock = True
        if perishable:
            if self._restock is None:
                raise DepotError("RETURN_POLICY_UNSET")
            restock = bool(self._restock)
        if restock:
            self._check_cap(wh, qty)
            self._add_lot(sku, wh, self._s["day"], qty)
        self._set_cash(self._s["cash"] + price * qty)
        self._s["returned"][sku] += qty

    # ---- transfer
    def transfer(self, sku, qty, from_wh, to_wh):
        return self._op(self._transfer, sku, qty, from_wh, to_wh)

    def _transfer(self, sku, qty, a, b):
        self._sku(sku)
        self._w(a)
        self._w(b)
        _posint(qty)
        if a == b:
            raise DepotError("SAME_WAREHOUSE")
        if self._stock(sku, a) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        self._check_cap(b, qty)
        fee = self._cfg["transfer_credit_cents_per_unit"] * qty
        if self._s["cash"] - fee < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        for d, n in self._take(sku, a, qty):
            self._add_lot(sku, b, d, n)
        self._set_cash(self._s["cash"] - fee)

    # ---- time
    def advance_day(self):
        return self._op(self._advance, blocks=True)

    def _advance(self):
        s = self._s
        d = s["day"]
        held = self._held()
        s["hist"][str(d)] = held
        s["day"] = d + 1
        self._set_cash(s["cash"] - self._cfg["storage_cents_per_unit_day"] * held)
        for sku in sorted(s["items"]):
            shelf = s["items"][sku]["shelf_life_days"]
            if shelf is None:
                continue
            for wh in self._wh:
                lots = s["lots"][sku][wh]
                gone = sum(q for ld, q in lots if s["day"] - ld > shelf)
                if gone:
                    s["lots"][sku][wh] = [l for l in lots if s["day"] - l[0] <= shelf]
                    events.emit(s, "EXPIRY", sku, wh, gone)
        if s["cash"] < 0 and not s["overdrawn"]:
            s["overdrawn"] = True
            events.emit(s, "OVERDRAWN")

    # ---- suppliers
    def place_order(self, supplier, sku, qty, due_day):
        return self._op(self._place, supplier, sku, qty, due_day)

    def _place(self, supplier, sku, qty, due_day):
        self._sku(sku)
        _posint(qty)
        rel = self._s["rel"].setdefault(supplier, suppliers.START)
        if suppliers.is_suspended(rel):
            raise DepotError("SUPPLIER_SUSPENDED")
        oid = self._s["next_order"]
        self._s["next_order"] = oid + 1
        self._s["orders"][str(oid)] = {"supplier": supplier, "sku": sku, "qty": qty,
                                       "due": due_day, "done": False}
        return oid

    def deliver(self, order_id, day, wh=None):
        return self._op(self._deliver, order_id, day, wh)

    def _deliver(self, order_id, day, wh):
        o = self._s["orders"].get(str(order_id))
        if o is None:
            raise DepotError("UNKNOWN_ORDER")
        if o["done"]:
            raise DepotError("ALREADY_DELIVERED")
        wh = self._wh[0] if wh is None else wh
        self._w(wh)
        late = day > o["due"]
        cost = self._s["items"][o["sku"]]["unit_cost"] * o["qty"]
        if late:
            if self._late_pct is None:
                raise DepotError("LATE_PENALTY_UNSET")
            cost = money.late_payment(cost, self._late_pct, self._mode)
        self._check_cap(wh, o["qty"])
        if self._s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._set_cash(self._s["cash"] - cost)
        self._add_lot(o["sku"], wh, self._s["day"], o["qty"])
        o["done"] = True
        sup = o["supplier"]
        before = self._s["rel"][sup]
        after = suppliers.after_delivery(before, late)
        self._s["rel"][sup] = after
        if suppliers.is_suspended(after) and not suppliers.is_suspended(before):
            events.emit(self._s, "SUPPLIER_SUSPENDED", sup)

    def reinstate(self, supplier):
        return self._op(self._reinstate, supplier)

    def _reinstate(self, supplier):
        if supplier not in self._s["rel"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        self._s["rel"][supplier] = suppliers.REINSTATED

    def reliability(self, supplier):
        if supplier not in self._s["rel"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self._s["rel"][supplier]

    # ---- audit / queries
    def audit(self, counts):
        return self._op(self._audit, counts)

    def _audit(self, counts):
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for sku, wh in counts:
            self._sku(sku)
            self._w(wh)
        for (sku, wh) in sorted(counts):
            ledger = self._stock(sku, wh)
            if ledger != counts[(sku, wh)]:
                events.emit(self._s, "AUDIT_MISMATCH", sku, wh, ledger, counts[(sku, wh)])

    def notifications(self):
        return events.read(self._s)

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._w(wh)
            return self._stock(sku, wh)
        return sum(self._stock(sku, w) for w in self._wh)

    def report(self):
        rows = []
        for sku in sorted(self._s["items"]):
            uc = self._s["items"][sku]["unit_cost"]
            for wh in sorted(self._wh):
                u = self._stock(sku, wh)
                rows.append((sku, wh, u, u * uc))
        return rows

    def turnover(self, start_day, end_day):
        if end_day < start_day:
            raise DepotError("BAD_RANGE")
        shipped = sum(q for d, q in self._s["ship_log"] if start_day <= d <= end_day)
        vals = []
        for d in range(start_day, end_day + 1):
            if str(d) in self._s["hist"]:
                vals.append(self._s["hist"][str(d)])
            elif d == self._s["day"]:
                vals.append(self._held())
        if not vals:
            return None
        avg = sum(vals) / len(vals)
        if avg == 0:
            return None
        return shipped / avg

    @property
    def cash(self):
        return self._s["cash"]

    @property
    def day(self):
        return self._s["day"]

    # ---- undo / persistence
    def undo(self):
        if self._blocked:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        self._s = self._undo
        self._undo = None

    def save(self):
        return json.dumps({"version": 1, "state": self._s}, sort_keys=True)

    def load(self, s):
        try:
            data = json.loads(s)
            if not isinstance(data, dict) or data.get("version") != 1:
                raise ValueError
            st = data["state"]
            keys = set(self._s)
            if not isinstance(st, dict) or set(st) != keys:
                raise ValueError
            if st["warehouses"] != self._wh:
                raise ValueError
            if not isinstance(st["cash"], int) or not isinstance(st["day"], int):
                raise ValueError
            for sku in st["items"]:
                for w in self._wh:
                    for d, q in st["lots"][sku][w]:
                        int(d), int(q)
                    bool(st["below"][sku][w])
                int(st["shipped"][sku]), int(st["returned"][sku])
                int(st["items"][sku]["unit_cost"])
                int(st["items"][sku]["reorder_level"])
            for n in st["notes"]:
                tuple(n)
            for o in st["orders"].values():
                o["supplier"], o["sku"], o["qty"], o["due"], o["done"]
            int(st["next_order"])
        except Exception:
            raise DepotError("BAD_SAVE")
        self._s = st
        self._undo = None
        self._blocked = False
</file>

<notes>
- Open owner decisions are not chosen. `late_penalty_pct` (C18) and `restock_returned_perishables` (C23) are keyword arguments that default to None. A late `deliver` raises `LATE_PENALTY_UNSET`, and returning a perishable raises `RETURN_POLICY_UNSET`, until they are set. `rounding_mode` is a required argument with no default (C31).
- Rounding uses `decimal` directly, not `vendor/rounding.py`, so the vendor file is untouched. The vendor file's `ROUND_HALF_UP` branch is `floor(d + 0.5)`, which would round negative amounts wrongly. No negative amounts arise here, but I did not want to depend on it.
- `data.toml` has `FILM` with `shelf_life_days = 0`, which conflicts with C13 (perishable means at least 1). `add_item` raises `BAD_SHELF_LIFE` for values below 1, so adding FILM verbatim from the table will fail. I asked the owner about this.
- The data key `transfer_credit_cents_per_unit` is treated as a cost of 25 cents per unit charged to the sender (C11). Insufficient cash gives `INSUFFICIENT_FUNDS`.
- `deliver(order_id, day, wh=None)`: the spec gives no warehouse, so I added an optional `wh` that defaults to the first warehouse. Delivery pays `unit_cost × qty`, reduced by the late penalty if late. It stocks a lot, fails with `INSUFFICIENT_FUNDS` or `CAPACITY` where applicable, and then updates reliability. `SUPPLIER_SUSPENDED` is emitted when reliability crosses from above 1 to 1 or below.
- `undo()` restores a full snapshot, including notifications, and works once. After `advance_day()` it raises `UNDO_BLOCKED`. With nothing to undo it raises `NOTHING_TO_UNDO`. `load` clears undo.
- `OVERDRAWN` is emitted on the transition to negative cash, checked at the end of `advance_day`. The flag re-arms when cash is back at or above 0. `REORDER` is armed again once stock is above the level, and it is only emitted on shipment.
- `advance_day` increments the day first. The storage charge uses the units held at that moment. Expiry then discards lots whose age (`new_day − lot_day`) exceeds the shelf life, emitting one `EXPIRY` per (sku, wh).
- A bulk discount applies when `qty >= bulk_threshold`, rounded by the depot's mode. Returns refund `price × qty` with no discount. A transfer with the same source and destination warehouse raises `SAME_WAREHOUSE`.
- `turnover` is units shipped in days `[start, end]` divided by the mean of the daily held units, recorded at each `advance_day`, with the live count used for the current day. It returns None if the average is 0 or no day is covered.
- `report()` lists every (sku, wh) pair, including zero-unit rows.
- `load` requires the saved warehouses to match the constructor's, otherwise `BAD_SAVE`.
- `simulate` draws `randint(min, max)` per sku in sorted order each day, from `random.Random(seed)`, and omits zero-quantity orders.
</notes>
